'use strict';
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { norm, romkey, isLatin } = require('../src/norm');

// Snapshot copied from the app (test/fixtures/norm_cases.json, generated by build_bigdb.py).
// When the app fixture is present (local checkout) it is used, so parity is always current.
const appFixture = path.join(__dirname, '..', '..', 'test', 'fixtures', 'norm_cases.json');
const file = fs.existsSync(appFixture) ? appFixture : path.join(__dirname, 'fixtures', 'norm_cases.json');
const cases = JSON.parse(fs.readFileSync(file, 'utf8'));

test('norm() matches the Python contract', () => {
  for (const [input, expected] of Object.entries(cases.norm)) {
    assert.strictEqual(norm(input), expected, `norm(${JSON.stringify(input)})`);
  }
});

test('romkey() matches the Python contract', () => {
  for (const [input, expected] of Object.entries(cases.romkey)) {
    assert.strictEqual(romkey(input), expected, `romkey(${JSON.stringify(input)})`);
  }
});

test('isLatin', () => {
  assert.ok(isLatin('pyaar'));
  assert.ok(isLatin('perché?'));
  assert.ok(!isLatin('پیار'));
  assert.ok(!isLatin('123'));
});
